---@param idolLive3D_SuperTimeLineState_ table
function SuperTimeline_10302150:__init( idolLive3D_SuperTimeLineState_ )
    
    self.idolLive3D_SuperTimeLineState = idolLive3D_SuperTimeLineState_
    self.lastClipId = nil
    self.lastRefreshTime = 0

    self.nextClipInfosMap = {}


    self.EventSimpleTapInAnyTime  = Events.AddListener(IdolLive3D_States.EventSimpleTapInAnyTime, Bind(self, self._OnSimpleTapInAnyTime))

